export default [
    {
        path:'/',
        name:'auth-login',
        meta: {template: 'authencation-login'},
        children:[
          {
            path: "/auth/login",
            name:'login',
            component: () => import("../views/authentication/login/Login.vue"),
          },
        ]
    },
    {
        path:'/auth/register',
        name:'auth-register',
        meta: {template: 'authencation-login'},
        children:[
          {
            path: "/auth/register",
            name:'register',
            component: () => import("../views/authentication/register/Register.vue"),
          },
        ]
    }
]
